bl_info = {
    "name": "AI Mesh Cleanup Tool",
    "author": "3dflowhub",
    "version": (1, 0, 0),
    "blender": (3, 0, 0),
    "location": "View3D > Sidebar > 3D FlowHub",
    "description": "Clean up and prepare AI generated meshes for production",
    "category": "Object",
};

import bpy

class OBJECT_OT_ai_mesh_cleanup(bpy.types.Operator):
    """Apply transforms, remove loose geometry, and center origin"""
    bl_idname = "object.ai_mesh_cleanup"
    bl_label = "Clean Up AI Meshes"
    bl_options = {'REGISTER', 'UNDO'}

    def execute(self, context):
        selected_objects = [obj for obj in context.selected_objects if obj.type == 'MESH']

        if not selected_objects:

            self.report({'WARNING'}, "No mesh objects selected")
            return {'CANCELLED'}

        for obj in selected_objects:
            context.view_layer.objects.active = obj

            # Apply rotation and scale
            bpy.ops.object.transform_apply(location=False, rotation=True, scale=True)

            # Switch to edit mode for mesh cleanup
            bpy.ops.object.mode_set(mode='EDIT')

            # Remove loose geometry
            bpy.ops.mesh.delete_loose()

            # Remove doubles (merge by distance)
            bpy.ops.mesh.remove_doubles(threshold=0.0001)

            # Switch back to object mode
            bpy.ops.object.mode_set(mode='OBJECT')

            # Set origin to geometry center
            bpy.ops.object.origin_set(type='ORIGIN_GEOMETRY', center='MEDIAN')

        self.report({'INFO'}, f"Successfully cleaned {len(selected_objects)} mesh(es).")
        return {'FINISHED'}

class VIEW3D_PT_ai_mesh_cleanup_panel(bpy.types.Panel):
    bl_label = "3D FlowHub Cleanup"
    bl_idname = "VIEW3D_PT_ai_mesh_cleanup"
    bl_space_type = 'VIEW_3D'
    bl_region_type = 'UI'
    bl_category = "3D FlowHub"

    def draw(self, context):
        layout = self.layout
        layout.operator("object.ai_mesh_cleanup")

classes = (
    OBJECT_OT_ai_mesh_cleanup,
    VIEW3D_PT_ai_mesh_cleanup_panel,
)

def register():
    for cls in classes:
        bpy.utils.register_class(cls)

def unregister():
    for cls in classes:
        bpy.utils.unregister_class(cls)

if __name__ == "__main__":
    register()
